Given a string s, find the longest substring which is a palindrome. If there are multiple answers, then find the first appearing substring.Examples:Input: s = "forgeeksskeegfor"Output: "geeksskeeg"Explanation: The longest substring that reads the same forward and backward is "geeksskeeg". Other palindromes like "kssk" or "eeksskee" are shorter.Input: s = "Geeks"Output: "ee"Explanation: The substring "ee" is the longest palindromic part in "Geeks". All others are shorter single characters.Input: s = "abc"Output: "a"Explanation: No multi-letter palindromes exist. So the first character "a" is returned as the longest palindromic substring.Try It YourselfTable of Content[Naive Approach] Generating all sub-strings - O(n^3) time and O(1) space[Better Approach - 1] Using Dynamic Programming - O(n^2) time and O(n^2) space[Better Approach - 2] Using Expansion from center - O(n^2) time and O(1) space[Expected Approach] Using Manacher’s Algorithm - O(n) time and O(n) space[Naive Approach] Generating all sub-strings - O(n3) time and O(1) spaceGenerate all possible substrings of the given string. For each substring, check if it is a palindrome.If it is, update the result if its length is greater than the longest palindrome found so far.
            C++

    #include <iostream>
using namespace std;

// function to check if a substring 
// s[low..high] is a palindrome
bool checkPal(string &s, int low, int high) {
    while (low < high) {
        if (s[low] != s[high])
            return false;
        low++;
        high--;
    }
    return true;
}

// function to find the longest palindrome substring
string getLongestPal(string& s) {

    int n = s.size();

    // all substrings of length 1 are palindromes
    int maxLen = 1, start = 0;

    // nested loop to mark start and end index
    for (int i = 0; i < n; i++) {
        for (int j = i; j < n; j++) {

            // check if the current substring is 
            // a palindrome
            if (checkPal(s, i, j) && (j - i + 1) > maxLen) {
                start = i;
                maxLen = j - i + 1;
            }
        }
    }

    return s.substr(start, maxLen);
}

int main() {
    string s = "forgeeksskeegfor";
    cout << getLongestPal(s) << endl;
    return 0;
}


